import{F as e,I as t,Z as n,t as r}from"./chunks/framework.BLmRAsdY.js";var i=JSON.parse(`{"title":"参与 Sync Engine 贡献","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/usage/contributing.md","filePath":"zh-Hans/usage/contributing.md","lastUpdated":1795199667000}`),a={name:`zh-Hans/usage/contributing.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="参与-sync-engine-贡献" tabindex="-1">参与 Sync Engine 贡献 <a class="header-anchor" href="#参与-sync-engine-贡献" aria-label="Permalink to “参与 Sync Engine 贡献”">​</a></h1><p>Sync Engine 欢迎对插件核心、模块和文档的任何贡献，也欢迎 issue 和功能请求。</p><h2 id="issue-政策" tabindex="-1">Issue 政策 <a class="header-anchor" href="#issue-政策" aria-label="Permalink to “Issue 政策”">​</a></h2><p>Sync Engine 仓库接受两类 issue：bug 报告和功能请求。</p><h3 id="bug-报告" tabindex="-1">Bug 报告 <a class="header-anchor" href="#bug-报告" aria-label="Permalink to “Bug 报告”">​</a></h3><p><strong>Bug 报告的 issue 必须包含</strong>：</p><ul><li>清晰的描述和复现步骤</li><li>你正在使用的所有模块的列表</li><li>你使用的存储服务</li><li>同步过程中出现的 bug，请提供从 <code>Development</code> 设置导出的日志</li></ul><p><strong>不得包含</strong>：</p><ul><li>关于你自己的任何敏感信息</li><li>多个 bug：请分开提交 issue</li><li>投机性的&quot;根因&quot;猜测或&quot;修复方案&quot;：如果你已经走到了这一步，你可能更想提交 pull request。</li></ul><p>维护者已请求澄清 / 协同测试，但报告者未提供任何相关信息的 bug 报告，72 小时后关闭；报告者声称协同测试但没有提供后续信息的，同样在 72 小时后关闭。</p><h3 id="功能请求" tabindex="-1">功能请求 <a class="header-anchor" href="#功能请求" aria-label="Permalink to “功能请求”">​</a></h3><p><strong>功能请求包含</strong>：</p><ul><li>对该功能应如何工作的清晰描述</li><li>（可选）你的实现想法，如果你愿意参与头脑风暴</li></ul><p>功能请求是普通的 issue，但经过一些沟通后，维护者会把请求移到一个专门的 meta issue 中方便管理。</p><p>我们<strong>强烈建议</strong>你在提交功能请求之前，先尝试自己写一个 Sync Engine 模块来实现需求，因为 Sync Engine 的可扩展性很强，大多数功能都能用模块实现。Sync Engine 还提供官方 SDK、文档和 AI agent skill 来辅助模块开发。Sync Engine monorepo 中有大量模块示例。</p><h2 id="fork-政策" tabindex="-1">Fork 政策 <a class="header-anchor" href="#fork-政策" aria-label="Permalink to “Fork 政策”">​</a></h2><p>Sync Engine 欢迎有利于 Sync Engine monorepo 发展的 fork。</p><p>但是，正如 <a href="https://docs.obsidian.md/Developer+policies#Forks" target="_blank" rel="noreferrer">Obsidian 开发者政策</a>所述，只要 Sync Engine 仓库保持活跃或维护者未允许，Sync Engine 禁止任何形式的恶意 fork，即把它作为另一个独立插件提交到 Obsidian 官方插件目录。维护者发现后会举报。</p><p>与其再造一个同步插件，我们强烈建议你开发一个 Sync Engine 模块。Sync Engine 核心高度优化且久经实战，它提供的便捷 SDK 让你自由定制而无需重复造轮子。</p><h2 id="向-monorepo-贡献代码" tabindex="-1">向 Monorepo 贡献代码 <a class="header-anchor" href="#向-monorepo-贡献代码" aria-label="Permalink to “向 Monorepo 贡献代码”">​</a></h2><h3 id="monorepo-如何运作" tabindex="-1">Monorepo 如何运作 <a class="header-anchor" href="#monorepo-如何运作" aria-label="Permalink to “Monorepo 如何运作”">​</a></h3><p><strong>技术栈</strong>：</p><p>项目使用：</p><ul><li><strong>TypeScript 7</strong> 作为编程语言</li><li><strong>Bun</strong> 作为包管理器和任务运行器</li><li><strong>Turbo</strong> 管理 monorepo</li><li><strong>Tsdown</strong> 负责构建</li><li><strong>Oxlint 和 Bun fmt</strong> 负责检查与格式化</li><li><strong>VitePress</strong> 搭建文档网站</li></ul><p>插件核心使用：</p><ul><li><strong>Solid.js</strong> 和 <strong>TailwindCSS</strong>（经 UnoCSS）构建 UI</li><li>自研包 <strong>SynthKernel</strong> 做依赖注入</li><li>自研包 <strong>Uni-KV</strong> 提供 IndexedDB 和内存数据库</li></ul><p><strong>Monorepo 结构</strong>：</p><div class="language-txt" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Sync Engine Monorepo</span></span>
<span class="line"><span>├── docs          - Documentation website</span></span>
<span class="line"><span>├── blueprint     - Internal mechanisms</span></span>
<span class="line"><span>├── packages</span></span>
<span class="line"><span>│   ├── plugin    - Core plugin and SDK (@hesprs/sync-engine-sdk)</span></span>
<span class="line"><span>│   ├── shared    - Shared utilities (@repo/shared)</span></span>
<span class="line"><span>│   └── ...       - Others are all official modules</span></span>
<span class="line"><span>├── modules.json  - Official module source, records all official modules</span></span>
<span class="line"><span>└── tsconfig.json - TypeScript config for all packages</span></span></code></pre></div><p><strong>命令</strong>：</p><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>bun dev</code></td><td>构建且不清空 dist 文件夹</td></tr><tr><td><code>bun compile</code></td><td>构建并清空</td></tr><tr><td><code>bun dev:plugin</code></td><td>构建插件，不清空 dist</td></tr><tr><td><code>bun build:plugin</code></td><td>构建插件并清空</td></tr><tr><td><code>bun fix</code></td><td>格式化并修复可修复的检查错误</td></tr><tr><td><code>bun check</code></td><td>检查类型、lint 和格式</td></tr><tr><td><code>bun tests</code></td><td>运行所有测试</td></tr><tr><td><code>bun &lt;command&gt; -F &lt;package-name&gt;</code></td><td>针对单个包运行命令</td></tr></tbody></table><p><strong>CI/CD</strong>：</p><p>CI 对每个 pull request 的提交运行，执行 <code>bun check</code> 和 <code>bun tests</code>。任何一项失败，pull request 都无法合并。</p><p>核心插件的发布由任意 tag push 触发。含连字符的 tag 触发预发布，不含连字符的 tag 触发正式发布。发布工作流会提取 <code>packages/plugin/CHANGELOG.md</code> 中对应的描述作为发布详情。</p><p>模块二进制文件与文档网站一起发布在 GitHub Pages 上（为什么？更好的 CDN 和更少的速率限制）。当文档目录或 <code>modules.json</code> 的变更被推送到 main 分支时，部署自动运行。</p><p>SDK 包发布到 npm，版本与插件保持一致。发布依赖手动触发工作流。</p><h3 id="提交-pull-request" tabindex="-1">提交 Pull Request <a class="header-anchor" href="#提交-pull-request" aria-label="Permalink to “提交 Pull Request”">​</a></h3><p>你可以为调试或新功能提交 pull request。修复 bug 的 pull request 必须至少引用一个开放的 issue。</p><p>提交信息格式：<code>&lt;title&gt;(&lt;scope&gt;): &lt;message&gt;</code>。信息保持简洁，避免冗长的 &quot;files changed&quot; 或 ASCII 画。</p><p>如果你的贡献创建了新模块、包含复杂实现，或更改了核心 SDK API，则必须在 <code>docs</code> 目录中补充相关实现文档。</p><p>为方便维护者，审查交流使用英文。与 issue 相同，如果一个 pull request 未通过审查或 CI，且超过 72 小时没有任何有意义的变更，PR 将被关闭。</p><h4 id="模块贡献" tabindex="-1">模块贡献 <a class="header-anchor" href="#模块贡献" aria-label="Permalink to “模块贡献”">​</a></h4><p>如果你想贡献一个新模块，请把它做成 <code>packages</code> 下的一个包。模块的 <code>package.json</code> 至少要包含：</p><div class="language-json" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;contributors&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;the-name-to-call-you&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;github&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;your-github-account-name&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }] }</span></span></code></pre></div><p>然后修改仓库根目录的 <code>modules.json</code>，把你的模块加进去：</p><div class="language-json" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Module Name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your-module&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;icon&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;puzzle&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Description for your module&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.0.1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;main&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://sync.consensia.cc/modules/module-name.js&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>PR 被接受后，你的模块会成为官方模块的一部分。之后关于该模块的 issue 和 pull request 也由你负责。</p><p>如果你的 pull request 包含对现有模块的实质性修改，也可以把你的信息加入 <code>contributors</code> 字段。</p><h4 id="ai-贡献" tabindex="-1">AI 贡献 <a class="header-anchor" href="#ai-贡献" aria-label="Permalink to “AI 贡献”">​</a></h4><p>提交 pull request 或 issue 时，请与维护者清晰沟通。如果你的文字表现出明显的 AI 痕迹（自信的错误断言、冗长而空洞的行话），维护者保留用 AI 生成的文本回复的权利。</p><p>Sync Engine 仓库总体上接受 AI 辅助的 pull request，模块方面尤其如此，只要它们：</p><ul><li>通过 CI</li><li>通过审查</li><li>代码质量达到维护者可接受的标准</li><li>能够对后续维护保持负责</li></ul><p>代码可以由 AI 编写；但提交 pull request 时，Sync Engine 要求作者必须是真实人类的 GitHub 账户。<strong>公司 AI agent 实体的任何名称都不得出现在共同作者列表、提交信息和代码中。</strong> 原因如下：</p><ul><li>由 AI 完成的提交往往说明背后的人类缺乏足以承担后续维护的开发能力。</li><li>本仓库代码的版权属于对应的作者和贡献者，AI 共同署名会给代码归属带来歧义。</li></ul>`,53)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};